import Foundation

struct IsoldeJournalEntry {
    let number: Int
    let title: String
    let localLanguage: Bool
    let illustration: String?
    let journal: String
    static let entries: [IsoldeJournalEntry] = [
        IsoldeJournalEntry(number: 1, title: "Catatan Pertama Isolde", localLanguage: true, illustration: "A village in the valley", journal: "Aku menulis ini sebelum matahari benar benar naik, ketika semua orang masih mengira aku tidur di rumah.\nJika ada yang menemukan buku ini, mungkin mereka akan menganggap aku bodoh. Mungkin memang begitu. Tidak ada orang waras yang meninggalkan lembah dengan sengaja. Orang tua selalu berkata bahwa hutan bukan tempat untuk dilalui, bahwa bukit bukan untuk diseberangi, dan bahwa dunia di luar sana sudah lama selesai untuk manusia.\nTetapi aku tidak bisa terus menerima jawaban yang sama hanya karena jawaban itu diwariskan. Setiap malam aku melihat kabut turun dari pepohonan, dan setiap pagi orang orang kembali bekerja seolah kabut itu tidak pernah ada. Mereka menyebutnya perlindungan. Mereka menyebutnya berkah. Aku hanya melihatnya sebagai dinding.\nAku takut. Tanganku gemetar ketika menggambar desa ini. Aku menggambarnya supaya jika aku tidak kembali, setidaknya ada bagian dari rumah yang ikut bersamaku.\nAku pergi bukan karena membenci desa. Aku pergi karena terlalu lama mencintainya sampai aku takut tidak pernah berani meninggalkannya."),
        IsoldeJournalEntry(number: 2, title: "Isolde Menghadapi The Hollow", localLanguage: true, illustration: "A figure holding a blade against a shadow", journal: "Aku melihatnya pertama kali di antara batang batang pohon yang mati.\nAwalnya kupikir itu bayangan. Lalu bayangan itu bergerak melawan arah angin. Tidak ada wajah, tetapi aku tahu ia melihatku. Tidak ada mulut, tetapi aku mendengar napasnya di dalam kepalaku.\nAku berlari sampai kakiku tersangkut akar. Saat jatuh, aku berpikir tentang desa, tentang ibuku, tentang betapa bodohnya aku karena merasa dunia luar harus memberiku jawaban. Rasa takut memenuhi dadaku sampai aku tidak bisa bernapas.\nLalu sesuatu berubah.\nAku tidak berhenti takut. Aku hanya berhenti memohon agar rasa takut itu pergi. Aku ingat berkata pada diriku sendiri, jika aku mati di sini, setidaknya aku mati karena pilihanku sendiri.\nSaat itulah tanganku terasa panas. Bukan seperti api, lebih seperti ada sesuatu dari makhluk itu yang mengalir masuk ke tubuhku. Bayangan itu menjerit, atau mungkin aku yang menjerit. Di tanganku muncul bentuk seperti bilah yang tidak seluruhnya padat. Aku mengayunkannya tanpa tahu caranya.\nMakhluk itu mundur.\nAku masih hidup.\nAku tidak tahu apa yang terjadi. Aku hanya tahu bahwa sesuatu dari dirinya sekarang ada di dalam diriku."),
        IsoldeJournalEntry(number: 3, title: "Hipotesa Isolde", localLanguage: true, illustration: nil, journal: "Aku membaca ulang catatan sebelumnya berkali kali. Tidak ada bagian yang terasa masuk akal, tetapi kejadian itu nyata. Bilah itu muncul lagi ketika aku mencoba mengingat makhluk tersebut, walau bentuknya lebih lemah.\nAku mulai memperhatikan satu hal: makhluk itu mendekat ketika aku panik. Ia seperti tahu bagian mana dari diriku yang paling ingin kusembunyikan. Tetapi saat aku berhenti melawan rasa takutku, saat aku menerima bahwa takut adalah bagian dari diriku, alirannya berubah.\nSeolah selama ini kami berdiri di dua sisi sungai.\nBiasanya emosiku mengalir ke arahnya. Namun pada saat itu, sesuatu dari dirinya mengalir kepadaku.\nMungkin inilah alasan desa selalu mengajarkan ketenangan. Mungkin hutan di sekitar lembah bukan sekadar tempat terlarang, melainkan sesuatu yang menahan emosi kami agar tidak terdengar oleh makhluk makhluk itu.\nAku tidak tahu apakah makhluk itu punya nama. Di desaku, anak kecil hanya mengenalnya sebagai cerita untuk menakuti kami agar tidak pergi jauh.\nAku akan menyebutnya Hollow.\nKosong, tetapi lapar."),
        IsoldeJournalEntry(number: 4, title: "Isolde Semakin Sering Melawan The Hollow", localLanguage: true, illustration: "A lone figure surrounded by shadows", journal: "Hari ini aku mengalahkan tiga Hollow.\nMenulis kalimat itu membuatku merasa seperti sedang membual kepada orang yang tidak ada. Tetapi aku harus mencatatnya. Mereka tidak semuanya sama. Ada yang bergerak seperti asap, ada yang berat seperti tubuh binatang, ada yang hanya berupa suara yang memanggil namaku dengan suara orang yang kurindukan.\nSetiap kali aku berhasil tetap berdiri di tengah rasa takut, kekuatanku muncul lebih cepat. Bilah itu kini tidak hanya satu. Kadang ia pecah menjadi serpihan kecil di sekeliling lenganku. Kadang ia melebar seperti perisai.\nAku mulai mengerti: bentuknya mengikuti pikiranku. Saat ingin lari, ia ringan. Saat ingin bertahan, ia menebal. Saat marah, ia menjadi tajam sampai sulit kuhentikan.\nIni membuktikan dugaanku. Hollow tidak hanya memakan emosi. Mereka membawa emosi. Jika aku dapat menerima emosi itu tanpa tenggelam, aku dapat mengambil sebagian kekuatan mereka.\nTetapi ada hal yang belum bisa kujelaskan. Setelah pertarungan selesai, aku masih merasakan sisa rasa yang bukan milikku. Kesedihan tanpa wajah. Amarah tanpa sebab. Kerinduan pada tempat yang tidak pernah kukenal."),
        IsoldeJournalEntry(number: 5, title: "Menemukan Reruntuhan Peradaban", localLanguage: true, illustration: "An abandoned village", journal: "Aku menemukan desa yang bukan desaku.\nAtau lebih tepatnya, sisa dari desa. Rumah rumahnya sudah roboh. Jalan batunya tertutup akar. Ada sumur di tengah permukiman, tetapi airnya hitam dan tidak memantulkan langit.\nYang membuatku takut bukan kehancurannya. Yang membuatku takut adalah benda benda kecil yang tertinggal: mangkuk pecah, mainan kayu, kain yang sudah hampir menyatu dengan tanah. Tempat ini pernah hidup. Orang orang pernah memasak, tertawa, bertengkar, membesarkan anak, lalu entah bagaimana semuanya hilang.\nHollow lebih banyak muncul di sini. Mereka keluar dari rumah kosong, dari balik dinding runtuh, dari sumur. Mereka seperti tidak menjaga tempat ini, tetapi terikat padanya.\nAku menemukan ukiran yang mirip dengan lambang lama di balai desaku. Garisnya berbeda, tetapi bentuk dasarnya sama. Jika ini benar, maka kami bukan orang pertama di pulau ini. Atau mungkin, kami semua berasal dari orang orang yang sama dan terpisah begitu lama sampai saling melupakan.\nAku mulai berpikir bahwa Hollow tetap ada bukan hanya karena manusia yang masih hidup. Tempat ini penuh sisa emosi. Ketakutan yang tidak selesai. Perpisahan yang tidak sempat diucapkan. Kemarahan yang membusuk bersama rumah rumah kosong.\nPulau ini mengingat lebih banyak daripada manusia."),
        IsoldeJournalEntry(number: 6, title: "Efek Samping Kekuatan", localLanguage: true, illustration: nil, journal: "Aku tidak yakin apakah catatan ini masih milikku.\nAda hari ketika aku bangun dengan menangis, tetapi aku tidak tahu siapa yang kurindukan. Ada malam ketika aku marah pada suara daun, pada batu, pada napasku sendiri. Aku melihat tanganku dan merasa tangan itu pernah menjadi milik orang lain.\nKekuatan itu masih datang ketika kupanggil. Lebih cepat dari sebelumnya. Terlalu cepat. Kadang aku bahkan tidak perlu takut. Cukup mengingat rasa takut, dan ia sudah berada di sana, menunggu.\nAku membaca catatan pertamaku. Gadis yang menulisnya terdengar jauh. Ia takut meninggalkan desa. Aku iri padanya. Takutnya masih sederhana. Takutnya masih punya nama.\nSekarang di dalam diriku terlalu banyak suara.\nAku pernah berpikir Hollow itu kosong. Aku salah. Mereka penuh dengan hal hal yang ditinggalkan manusia, dan aku telah mengambil terlalu banyak.\nJika seseorang membaca ini dan menemukan gambar gambarku, jangan percaya bahwa kekuatan adalah jawaban. Kekuatan hanya membuatmu mampu berjalan lebih jauh. Ia tidak memberitahumu kapan harus berhenti.\nAku harus berhenti.\nAku hanya tidak tahu apakah masih ada cukup diriku untuk melakukannya."),
        IsoldeJournalEntry(number: 7, title: "Among the old stones", localLanguage: false, illustration: nil, journal: "Found this book beneath the fallen watchtower north of home. Most of the writing means nothing to me. Now and then a letter looks almost familiar, but then the resemblance slips away.\n\nThe drawings are another matter. A village tucked into a valley. Woods thicker than ours. And that dark shape from the stories they told us as children. We never gave it a name. It was simply the thing waiting for anyone foolish enough to wander.\n\nAgnes said the book probably belonged to a madwoman. I agreed and put it in my bag. She still had a small stone in her hand, and for a moment I thought she might throw it at me.\n\nShe has agreed to come. Reluctantly.\n\nSomeone walked these roads before us. There were other villages, other people. I cannot stop wondering how we came to forget them."),
        IsoldeJournalEntry(number: 8, title: "Under the pale trees", localLanguage: false, illustration: "A shape in the mist", journal: "The drawing was real.\n\nAgnes saw it first. She stopped halfway through a sentence and caught my arm hard enough to hurt. Something was moving through the mist between the rocks. No eyes. No feet. Still, it knew where we were.\n\nI would like to write that I stood my ground.\n\nI ran.\n\nWe stumbled down the slope until my feet bled. Agnes nearly fell twice. I should have reached for her sooner. I was afraid to look back.\n\nIt stopped at the pale trees. I do not know why. Perhaps these woods shelter us as the valley does. Perhaps we were only lucky.\n\nI have tried to draw what I saw. A poor likeness, but enough. Whoever filled the first pages had seen it too.\n\nTonight I would give almost anything to read her words."),
        IsoldeJournalEntry(number: 9, title: "After the rain", localLanguage: false, illustration: "A spear against the dark", journal: "My hands have stopped shaking enough to write.\n\nIt found us beneath the overhang. Rain everywhere, and then mist so thick I could hardly see Agnes beside me. She held her knife with both hands.\n\nWhen it came, I pushed her away. There was no brave thought behind it. I simply moved.\n\nThen I was on my back, feeling something pull at my chest. As though my fear had become a thread it could swallow.\n\nI thought: this is where I die.\n\nI was still afraid. But for one moment I stopped wishing I were someone who wasn't.\n\nSomething pressed back. A weight settled into my empty hand. I swung, and a short spear of dark light struck the thing away.\n\nAgnes kept calling my name. I had no answer for her.\n\nThere is a drawing like this in the older pages. Someone holding a weapon against the dark.\n\nWas she trying to warn us?"),
        IsoldeJournalEntry(number: 10, title: "Still awake", localLanguage: false, illustration: nil, journal: "I have spent most of the night with the older pages spread across my knees. Agnes says staring will not teach me the language. She is right, as usual.\n\nBut look at the drawings: a hand, a chest, lines passing between a person and the thing in the woods.\n\nWhen I panicked, it seemed to grow stronger. When I stopped fighting the fact that I was afraid, something came back the other way.\n\nCould that be it? Not courage. Not an empty mind. Fear, allowed to be there without deciding everything.\n\nI should not call this an answer yet.\n\nAgnes says I am turning a wound into a theory before it has even closed. Perhaps writing is easier than remembering how close I came.\n\nI think I understand why the first writer drew so much. If the words fail whoever finds this next, perhaps a picture will reach them."),
        IsoldeJournalEntry(number: 11, title: "Kekalahan Elias", localLanguage: true, illustration: "A broken spear in the dark", journal: "Aku menulis di buku Elias karena ia tidak bisa menulis lagi.\nAku tidak tahu apakah aku membenci buku ini atau membutuhkannya. Elias selalu menulis seolah kata kata bisa membuat dunia lebih masuk akal. Sekarang aku ingin merobek semua halaman yang membuatnya percaya bahwa ia bisa memahami makhluk itu.\nYang menyerang kami malam itu bukan seperti yang sebelumnya. Ia memakai suara orang orang yang kami kenal. Suara ibuku. Suara adik Elias. Lalu, ketika Elias mulai marah, bentuknya menjadi lebih jelas.\nAku melihatnya. Semakin Elias ingin melindungiku, semakin besar rasa takutnya kehilangan aku. Semakin ia takut, semakin makhluk itu kuat.\nElias mencoba menggunakan tombaknya. Untuk sesaat aku yakin ia akan menang. Lalu makhluk itu membuka tubuhnya seperti lubang yang tidak punya dasar, dan tombak Elias patah sebelum menyentuh pusatnya.\nIa masih berdiri di depanku.\nBahkan setelah kakinya tidak kuat lagi.\nAku menariknya, memanggil namanya, memohon agar ia lari. Ia menoleh dan tersenyum seperti orang bodoh. Seperti orang yang ingin membuatku percaya semuanya baik baik saja.\nMakhluk itu menelannya dalam kabut hitam.\nAku tidak melihat tubuhnya jatuh.\nAku hanya menemukan buku ini, basah oleh hujan, terbuka di halaman tempat ia menulis bahwa rasa takut bisa diterima.\nAku tidak bisa menerima ini."),
        IsoldeJournalEntry(number: 12, title: "Agnes Melanjutkan Perjalanan Seorang Diri", localLanguage: true, illustration: nil, journal: "Aku berjalan karena berhenti terasa lebih menakutkan.\nSetiap kali aku duduk terlalu lama, aku mendengar suara Elias di belakangku. Kadang ia memanggil namaku. Kadang ia tertawa pelan, seperti saat ia berhasil membuatku ikut dalam rencana bodohnya. Aku tahu itu bukan dia. Aku tahu makhluk itu memakai suaranya.\nTetapi mengetahui tidak membuatnya lebih mudah.\nAku mencoba melakukan apa yang Elias tulis. Menerima rasa takut. Menerima rasa bersalah. Menerima bahwa aku masih hidup dan ia tidak.\nAku gagal.\nSetiap kali makhluk itu mendekat, yang kurasakan hanya satu hal: seharusnya aku yang tertinggal. Pikiran itu membuat dadaku penuh sampai aku tidak bisa bernapas. Jika kekuatan memang muncul saat seseorang berdamai dengan emosinya, maka tidak ada apa pun yang akan muncul dariku.\nAku tidak berdamai.\nAku hanya membawa kesalahan ini dari satu tempat ke tempat lain.\nBuku ini sekarang terlalu berat, tetapi aku tidak bisa meninggalkannya. Ada tulisan orang pertama yang tidak kupahami, tulisan Elias yang terlalu kupahami, dan sekarang tulisanku sendiri yang berharap tidak pernah kubutuhkan.\nJika ada orang setelahku membaca bagian Elias, ketahuilah: ia bukan orang yang tidak takut. Ia takut sampai akhir. Ia hanya tetap memilih berdiri."),
        IsoldeJournalEntry(number: 13, title: "Wujud Wujud Makhluk Yang Mengincar Manusia", localLanguage: true, illustration: "Mist, shadows, and a half-remembered face", journal: "Aku menggambar semua bentuk yang kulihat supaya aku tahu mana yang nyata dan mana yang hanya ada di kepalaku.\nPertama, kabut. Kabut yang bergerak terlalu lambat untuk disebut angin dan terlalu sengaja untuk disebut cuaca.\nKedua, suara. Tidak selalu keras. Kadang hanya bisikan dari arah yang salah. Kadang suara Elias memanggil dari balik pohon, padahal aku tahu ia tidak mungkin berada di sana.\nKetiga, bayangan yang berdiri di tempat terbuka saat matahari masih ada. Bayangan itu tidak mengikuti siapa pun. Ia menunggu sampai aku melihatnya, lalu menghilang.\nKeempat, wajah. Ini yang paling buruk. Makhluk itu tidak membuat wajah dengan sempurna. Selalu ada yang salah. Mata terlalu kosong. Senyum terlalu lama. Tetapi ketika aku lelah, kesalahan kecil itu hampir tidak terlihat.\nAku mulai berpikir makhluk itu tidak punya satu wujud asli. Mereka mengambil bentuk dari apa yang manusia bawa. Ketakutan memberi mereka arah. Rasa bersalah memberi mereka suara. Kerinduan memberi mereka wajah.\nElias mungkin akan membuat teori dari ini. Ia akan menulis dengan rapi, lalu meminta pendapatku.\nAku hanya bisa menggambar.\nMaafkan aku."),
        IsoldeJournalEntry(number: 14, title: "Ilustrasi Terakhir", localLanguage: false, illustration: "The coast seen from a hill — an unfinished sketch", journal: ""),
    ]
}
